import test from 'node:test';
import assert from 'node:assert/strict';
import {testServer} from './helpers.js';
function policy(result,secure,cleared=false) {
  const value=result.response.headers.get('set-cookie');assert(value);
  assert.match(value,/; Path=\//);assert.match(value,/; HttpOnly/);assert.match(value,/; SameSite=Strict/);
  assert.equal(/; Secure(?:;|$)/.test(value),secure);
  if(cleared){assert.match(value,/^crew_session=;/);assert.match(value,/Expires=Thu, 01 Jan 1970/);}
  else {assert.match(value,/^crew_session=crew1\.session\./);assert.match(value,/Max-Age=1209600/);}
}
for(const [baseUrl,secure] of [['http://localhost:4100',false],['https://crew.example.test',true]]) {
  test(baseUrl+' session issuance keeps canonical cookie policy on signup and login',async()=>{
    const server=await testServer({baseUrl});
    try {
      const api=server.agent(),identity={name:'Cookie Owner',email:'cookie@example.test',password:'cookie correct password'};
      const signup=await api('POST','/auth/signup',identity);assert.equal(signup.status,201);policy(signup,secure);
      const login=await api('POST','/auth/login',identity);assert.equal(login.status,200);policy(login,secure);
      assert.equal((await api('GET','/me')).data.user.email,identity.email);
    } finally {await server.close();}
  });
  test(baseUrl+' logout current-session revoke and password reset clear with the same cookie policy',async()=>{
    const server=await testServer({baseUrl});
    try {
      const api=server.agent(),identity={name:'Cookie Owner',email:'cookie@example.test',password:'cookie correct password'};
      await api('POST','/auth/signup',identity);
      const logout=await api('POST','/auth/logout',{});assert.equal(logout.status,200);policy(logout,secure,true);
      assert.equal((await api('GET','/me')).status,401);
      await api('POST','/auth/login',identity);
      const current=(await api('GET','/auth/sessions')).data.items.find(item=>item.current);assert(current);
      const revoke=await api('DELETE','/auth/sessions/'+current.id);assert.equal(revoke.status,200);policy(revoke,secure,true);
      assert.equal((await api('GET','/me')).status,401);
      await api('POST','/auth/login',identity);
      await api('POST','/auth/password/reset/request',{email:identity.email});
      const delivery=(await api('GET','/me/outbox?kind=reset')).data.items[0];
      const token=decodeURIComponent(delivery.payload.link.split('token=')[1]);
      const reset=await api('POST','/auth/password/reset',{token,password:'new cookie correct password'});
      assert.equal(reset.status,200);policy(reset,secure,true);
      assert.equal((await api('GET','/me')).status,401);
    } finally {await server.close();}
  });
}
